import time
from concurrent.futures import ThreadPoolExecutor


def run():
    with ThreadPoolExecutor(max_workers=5) as executor:
        futures = {
            executor.submit(time.sleep, 1): f"job_{i}"
            for i in range(5)
        }
        for future in futures.values():
            future.result()
    print("done 5")


if __name__ == "__main__":
    run()
